import React, { useState } from "react";
import { X, Send, Check } from "lucide-react";
import { COLLECTIONS } from "./Content";

// WhatsApp SVG Icon
const WhatsAppIcon = ({ size = 20 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="white" xmlns="http://www.w3.org/2000/svg">
    <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z"/>
  </svg>
);

export default function QuoteModal({ isOpen, onClose }) {
  const [formData, setFormData] = useState({ name: "", phone: "", eventType: "", message: "", categories: [] });
  const [submitted, setSubmitted] = useState(false);

  if (!isOpen) return null;

  const handleCategoryToggle = (categoryId) => {
    setFormData((prev) => ({
      ...prev,
      categories: prev.categories.includes(categoryId) ? prev.categories.filter((id) => id !== categoryId) : [...prev.categories, categoryId],
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const selectedCategories = formData.categories.map((id) => COLLECTIONS.find((c) => c.id === id)?.title).filter(Boolean).join(", ");
    const message = `*New Quote Request - D SAJAWAT*\n\n*Name:* ${formData.name}\n*Phone:* ${formData.phone}\n*Event Type:* ${formData.eventType}\n*Interested Categories:* ${selectedCategories || "General Inquiry"}\n*Message:* ${formData.message || "None"}`;
    window.open(`https://wa.me/919888919983?text=${encodeURIComponent(message)}`, "_blank");
    setSubmitted(true);
    setTimeout(() => { onClose(); setSubmitted(false); setFormData({ name: "", phone: "", eventType: "", message: "", categories: [] }); }, 2000);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="absolute inset-0" style={{ background: "rgba(0, 0, 0, 0.6)", backdropFilter: "blur(8px)" }} onClick={onClose} />
      <div className="relative w-full max-w-2xl max-h-[90vh] overflow-y-auto rounded-2xl glass-card" style={{ border: "2px solid rgba(212,175,55,0.3)" }}>
        <button onClick={onClose} className="absolute top-4 right-4 p-2 rounded-full transition-all hover:bg-gray-100"><X size={20} color="#1a080a" /></button>

        {submitted ? (
          <div className="flex flex-col items-center justify-center py-16 px-8">
            <div className="w-16 h-16 rounded-full flex items-center justify-center mb-6" style={{ background: "rgba(212, 175, 55, 0.15)", border: "2px solid #d4af37" }}><Check size={32} color="#d4af37" /></div>
            <h3 className="serif text-3xl mb-3" style={{ color: "#1a080a" }}>Request Sent!</h3>
            <p style={{ color: "rgba(26,8,10,0.7)", textAlign: "center" }}>We'll connect with you on WhatsApp shortly.</p>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-8 md:p-10">
            <div className="mb-8">
              <div className="overline mb-2">Get a Quote</div>
              <h2 className="serif" style={{ fontSize: "clamp(28px, 4vw, 42px)", fontWeight: 400, color: "#1a080a" }}>Let's decorate your event</h2>
            </div>

            <div className="mb-8 p-5 rounded-lg flex items-center justify-between" style={{ background: "rgba(37, 211, 102, 0.1)", border: "1px solid rgba(37, 211, 102, 0.3)" }}>
              <div>
                <p style={{ color: "#1a080a", fontWeight: 600 }}>Need quick response?</p>
                <p className="text-sm mt-1" style={{ color: "rgba(26,8,10,0.6)" }}>Chat directly on WhatsApp</p>
              </div>
              <button type="button" onClick={() => window.open("https://wa.me/919888919983?text=Hi!%20I%20need%20a%20quick%20quote%20for%20D%20SAJAWAT%20fabrics", "_blank")} className="flex items-center gap-2 px-5 py-3 rounded-full text-sm font-semibold text-white" style={{ background: "linear-gradient(135deg, #25d366 0%, #128c7e 100%)" }}><WhatsAppIcon size={18} />Chat Now</button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-5 mb-6">
              <div>
                <label className="block text-xs tracking-widest uppercase mb-2 font-semibold" style={{ color: "rgba(26,8,10,0.7)" }}>Your Name *</label>
                <input type="text" required className="field" placeholder="Enter your name" value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} />
              </div>
              <div>
                <label className="block text-xs tracking-widest uppercase mb-2 font-semibold" style={{ color: "rgba(26,8,10,0.7)" }}>Phone Number *</label>
                <input type="tel" required className="field" placeholder="Your phone number" value={formData.phone} onChange={(e) => setFormData({ ...formData, phone: e.target.value })} />
              </div>
            </div>

            <div className="mb-6">
              <label className="block text-xs tracking-widest uppercase mb-3 font-semibold" style={{ color: "rgba(26,8,10,0.7)" }}>Interested Products</label>
              <div className="flex flex-wrap gap-3">
                {COLLECTIONS.map((cat) => (
                  <button key={cat.id} type="button" onClick={() => handleCategoryToggle(cat.id)} className="px-4 py-2 rounded-full text-xs tracking-wider transition-all duration-200"
                    style={{ background: formData.categories.includes(cat.id) ? "linear-gradient(135deg, #d4af37, #f4d77a)" : "transparent", color: formData.categories.includes(cat.id) ? "#1a080a" : "rgba(26,8,10,0.7)", border: formData.categories.includes(cat.id) ? "none" : "1px solid rgba(212,175,55,0.4)", fontWeight: 600 }}>
                    {cat.title}
                  </button>
                ))}
              </div>
            </div>

            <div className="mb-8">
              <label className="block text-xs tracking-widest uppercase mb-2 font-semibold" style={{ color: "rgba(26,8,10,0.7)" }}>Your Message</label>
              <textarea className="field" rows={4} placeholder="Tell us about your requirements - quantities, measurements, event date..." value={formData.message} onChange={(e) => setFormData({ ...formData, message: e.target.value })} style={{ resize: "vertical", minHeight: 100 }} />
            </div>

            <button type="submit" className="btn-gold w-full justify-center text-lg py-4"><Send size={18} strokeWidth={1.6} />Send Quote Request via WhatsApp</button>
            <p className="text-center mt-4 text-xs" style={{ color: "rgba(26,8,10,0.5)" }}>We'll respond within 24 hours</p>
          </form>
        )}
      </div>
    </div>
  );
}
